def last_n(values, n):
    """Return the final n values, in order."""
    if n <= 0:
        return []
    start = max(0, len(values) - n)
    return values[start:]

def is_valid(user):
    """Whether the user may sign in: active accounts that are not locked."""
    return user.is_active and not user.is_locked

def normalize_whitespace(text):
    """Collapse every run of whitespace in text into a single space."""
    return " ".join(text.split())

def chunked(values, size):
    """Split values into consecutive chunks of at most size items."""
    if size <= 0:
        raise ValueError("size must be a positive number of items")
    return [values[start : start + size] for start in range(0, len(values), size)]
